import React, { useState } from "react";
import styles from "./faq.module.css";
import { useContext, useCallback } from "react";
import { CursorContext } from "../Cursor/CursorContextProvider";

const FAQ = () => {
  const [answersVisibility, setAnswersVisibility] = useState({
    0: false,
    1: false,
    2: false,
    3: false,
    4: false,
    5: false,
    6: false,
    7: false,
    8: false,
    9: false,
    10: false,
    11: false,
  });
  const [, setCursor] = useContext(CursorContext);

  const toggleCursor = useCallback(() => {
    setCursor(({ active }) => ({ active: !active }));
  });

  const toggleAnswer = (index) => {
    setAnswersVisibility((prevVisibility) => ({
      ...prevVisibility,
      [index]: !prevVisibility[index],
    }));
  };

  return (
    <div className={styles["faq-outer"]}>
      <div
        className={styles["q-outer"]}
        onClick={() => toggleAnswer(0)}
        onMouseEnter={toggleCursor}
        onMouseLeave={toggleCursor}
        style={{
          backgroundColor: answersVisibility[0] ? "#82f74f" : "initial",
        }}
      >
        <p>How is TERRAIN funded? Are you a not-for-profit organisation?</p>

        <div
          className={`${styles["q-answer"]} ${
            answersVisibility[0] ? "" : styles["hidden"]
          }`}
        >
          <p>
            / We are a for-profit initiative as a social enterprise and choose
            to be so in order to enable the longevity of our work, and remove
            reliance upon external funding support needed to start us up. We
            also think it’s important to remove reliance on funding bodies to
            make way and open opportunities in our communities for supporting
            new and emerging initiatives in the future. We self-finance and pay
            ourselves through our work alone, via studio memberships, space
            hire, book sales, consultation, workshops, public engagements, and
            various other services. This allows us to maintain the creative
            integrity of our projects and resources as they are not compromised
            with a need for monetisation. Being for-profit doesn’t make us
            raging capitalists. We all face many structural challenges as a
            direct result of our current form of capitalism that is
            fundamentally broken. Being a for-profit initiative means that we
            can be part of reimagining our economic system and work inside of it
            by taking direct responsibility for our decisions. We envision our
            future governed by principles of ecological economics, a pluralist
            view that sees the human economy as a subsystem of the global
            ecological system; thus, materials and energy flow as part of the
            larger transfer of materials within our biosphere.
          </p>
        </div>
      </div>

      <div
        className={styles["q-outer"]}
        onClick={() => toggleAnswer(1)}
        onMouseEnter={toggleCursor}
        onMouseLeave={toggleCursor}
        style={{
          backgroundColor: answersVisibility[1] ? "#82f74f" : "initial",
        }}
      >
        <p>How can I engage or support TERRAIN?</p>

        <div
          className={`${styles["q-answer"]} ${
            answersVisibility[1] ? "" : styles["hidden"]
          }`}
        >
          <p>
            / What we ask is that you make time to read a book, slow down, be
            open, ask a question, breathe, pay attention, extend your sense of
            self, and meet the community. You can be aware and critical of the
            systems and worldviews we accept, and be brave enough to attempt
            reimagining and shifting them for the better. If they feel
            incompatible and out-of-date, they probably are.
            <br></br>
            <br></br>
            You can also hire our space, become a studio member, volunteer at
            the bookshop ‘help desk’, purchase a book or gift voucher, attend an
            event, seek our services, recommend our services, volunteer with us,
            and tell your nice friends about us.
          </p>
        </div>
      </div>
      <div
        className={styles["q-outer"]}
        onClick={() => toggleAnswer(2)}
        onMouseEnter={toggleCursor}
        onMouseLeave={toggleCursor}
        style={{
          backgroundColor: answersVisibility[2] ? "#82f74f" : "initial",
        }}
      >
        <p>
          Are you hiring and do you take interns, work experience and
          volunteers?
        </p>

        <div
          className={`${styles["q-answer"]} ${
            answersVisibility[2] ? "" : styles["hidden"]
          }`}
        >
          <p>
            / We don’t have the bandwidth (yet) for more staff, we’d like to
            soon though as we continue to grow. As soon as paid positions are
            available we will make them known! For interns, work experience and
            volunteers, drop us an email to hello@terrain.earth with an
            introduction, your curiosity and a CV.
          </p>
        </div>
      </div>
      <div
        className={styles["q-outer"]}
        onClick={() => toggleAnswer(3)}
        onMouseEnter={toggleCursor}
        onMouseLeave={toggleCursor}
        style={{
          backgroundColor: answersVisibility[3] ? "#82f74f" : "initial",
        }}
      >
        <p>Where are you located?</p>
        <div
          className={`${styles["q-answer"]} ${
            answersVisibility[3] ? "" : styles["hidden"]
          }`}
        >
          <p>
            / 37.8136° S 144.9631° E; Wurundjeri Country, Naarm / Melbourne,
            Australia, Earth. Our physical bookshop, gallery and studio address
            is: 101-103 Brunswick Street, Ngár-go/Fitzroy, VIC, 3065, Australia.
            We also have a P.O. Box if you feel like sending us something: P.O.
            Box 4196, VIC, 3065, Australia.
          </p>
        </div>
      </div>
      <div
        className={styles["q-outer"]}
        onClick={() => toggleAnswer(4)}
        onMouseEnter={toggleCursor}
        onMouseLeave={toggleCursor}
        style={{
          backgroundColor: answersVisibility[4] ? "#82f74f" : "initial",
        }}
      >
        <p>Can we collaborate?</p>

        <div
          className={`${styles["q-answer"]} ${
            answersVisibility[4] ? "" : styles["hidden"]
          }`}
        >
          <p>
            / Our projects are either directly conceived or collaborative from
            the get-go - they can be one-off or ongoing. We are open to
            collaboration on new projects and we’d love to hear from you - send
            us an email to hello@terrain.earth if you feel so inclined!
          </p>
        </div>
      </div>
      <div
        className={styles["q-outer"]}
        onClick={() => toggleAnswer(5)}
        onMouseEnter={toggleCursor}
        onMouseLeave={toggleCursor}
        style={{
